{"rob": "robolang 1.3;

task sort_parts(robot arm, object item1, object item2, object item3, location feed, location s1_loc, location s2_loc, location bin_loc) {
    goal { object_at item1 s1_loc; object_at item2 s2_loc; object_at item3 bin_loc; }
    plan {
        move arm to feed;
        grasp arm item1;
        move arm to s1_loc;
        place arm item1 at s1_loc;
        move arm to feed;
        grasp arm item2;
        move arm to s2_loc;
        place arm item2 at s2_loc;
        move arm to feed;
        grasp arm item3;
        move arm to bin_loc;
        place arm item3 at bin_loc;
    }
}
", "task": "sort_parts", "bindings": [{"param": "arm", "id": "arm_a"}, {"param": "item1", "id": "p1"}, {"param": "item2", "id": "p2"}, {"param": "item3", "id": "p3"}, {"param": "feed", "id": "conveyor_in"}, {"param": "s1_loc", "id": "station1"}, {"param": "s2_loc", "id": "station2"}, {"param": "bin_loc", "id": "bin"}]}
